import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { CourseCategoryModel, ICourseCategoryModel } from '../../../../data/model/course/CourseCategoryModel';
import { GResponse } from '../../../../core/common/GResponse';

@Component({
  selector: 'app-admin-image-category',
  templateUrl: './admin-image-category.component.html',
  styleUrls: ['./admin-image-category.component.scss']
})
export class AdminImageCategoryComponent implements OnInit {

  @Input() selectedCategory = 'tuning';
  @Output() SelectEvent = new EventEmitter<ICourseCategoryModel>();

  mechanicCategories: CourseCategoryModel[] = [];
  tuningCategories: CourseCategoryModel[] = [];
  designeCategories: CourseCategoryModel[] = [];

  constructor() {

  }

  ngOnInit(): void {

    this.mechanicCategories = [];
    this.tuningCategories = [];
    this.designeCategories = [];

    GResponse.CourseCategory.forEach(c => {

      if (c.parentId == 1) {
        this.mechanicCategories.push(c);
      } else if (c.parentId == 2) {
        this.tuningCategories.push(c);
      } else if (c.parentId == 3) {
        this.designeCategories.push(c);
      }
    });
  }

  onClick(id: string | number, title: string, url: string, parentId: string | number) {

    this.SelectEvent.emit(new CourseCategoryModel(+id, title, url, +parentId));
  }
}
