import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { IonicModule } from '@ionic/angular';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { AccountInterceptor } from '../../../core/utility/account.interceptor';
import { CourseService } from '../../../data/service/course/course.service';
import { CourseComponent } from './course/course.component';
import { PriceModule } from '../../../core/pipe/price.module';
import { RouterModule } from '@angular/router';
import { TeacherCourseComponent } from './teacher-course/teacher-course.component';
import { AdminImageCategoryComponent } from './admin-image-category/admin-image-category.component';
import { CourseQuestionComponent } from './course-question/course-question.component';



@NgModule({
  declarations: [
    CourseComponent,
    TeacherCourseComponent,
    CourseQuestionComponent,
    AdminImageCategoryComponent],
  imports: [
    CommonModule,
    IonicModule,
    HttpClientModule,
    RouterModule,
    PriceModule
  ],
  providers: [
    CourseService,
    {
      provide: HTTP_INTERCEPTORS,
      useClass: AccountInterceptor,
      multi: true
    }
  ],
  exports: [CourseComponent, TeacherCourseComponent, CourseQuestionComponent, AdminImageCategoryComponent]
})
export class SharedCourseModule { }
