import { Component, Input, OnInit } from '@angular/core';
import { ICourseModel } from '../../../../data/model/course/CourseModel';
import { Router } from '@angular/router';
import { G } from '../../../../core/common/G';

@Component({
  selector: 'app-course',
  templateUrl: './course.component.html',
  styleUrls: ['./course.component.scss']
})
export class CourseComponent implements OnInit {

  @Input() course: ICourseModel;
  windowWidth = 1000;

  constructor(private router: Router) {

    G.getWindowWidth().subscribe(
      res => {
        this.windowWidth = res;
      }
    );
  }

  ngOnInit(): void {
  }

  getTeacherName() {

    if (this.course.teacher == undefined || this.course.teacher == null) {

      return '';
    }

    // tslint:disable-next-line: max-line-length
    return this.course.teacher.name != null ? this.course.teacher.name : '' + ' ' + this.course.teacher.family != null ? this.course.teacher.family : '';
  }

  onClick() {

    this.router
      .navigate(
        ['/Course', 'Id', this.course.id]);
  }

  onCheckNew() {

    let date1 = new Date(this.course.createDate);
    let date2 = new Date();

    let diff = date2.getTime() - date1.getTime();

    let days = Math.floor(diff / (1000 * 60 * 60 * 24));
    diff -= days * (1000 * 60 * 60 * 24);

    let hours = Math.floor(diff / (1000 * 60 * 60));
    diff -= hours * (1000 * 60 * 60);

    let mins = Math.floor(diff / (1000 * 60));
    diff -= mins * (1000 * 60);

    let seconds = Math.floor(diff / (1000));
    diff -= seconds * (1000);

    if (days < 30) {

      return true;
    } else {

      return false;
    }
  }
}
